def test_nobody_changes_own_access(people):
    a = people["admin"]
    me = ok(a.get("/api/v1/me"))["user"]["id"]
    e = ok(a.post(f"/api/v1/admin/users/{me}/grants", json={
        "perm_key": "finance.view", "effect": "deny", "reason": "self change"}), 403)
    assert e["error"] == "CANNOT_CHANGE_OWN_ACCESS"
